test('source migration provides tenant FORCE RLS, typed parent FKs and unique active/dispatch invariants and exact normal source registration',()=>{const sql=readFileSync(new URL('../server/212_local_woo_read_lane.sql',import.meta.url),'utf8');for(const t of ['controls','commands','occurrences','dispatches'])assert(sql.includes('CREATE TABLE local_woo_read_'+t));assert(sql.includes('FORCE ROW LEVEL SECURITY'));assert(sql.includes('WITH CHECK(tenant_id='));assert(sql.includes('FOREIGN KEY(tenant_id,job_id)'));assert(sql.includes("WHERE state='started'"));assert(sql.includes("WHERE state<>'done'"));assert(!sql.includes('GRANT DELETE'));assert(!source.includes('setInterval('));assert(!source.includes('startWorker('));const {sourceDdlMigrationPlan}=createRequire(import.meta.url)('../tools/build/source-ddl-migration-plan.mjs');const plan=sourceDdlMigrationPlan(readFileSync(new URL('../server/db.ts',import.meta.url),'utf8'));const rows=plan.filter((r:any)=>r.name==='212_local_woo_read_lane'||r.file==='212_local_woo_read_lane.sql');assert.deepEqual(rows,[{name:'212_local_woo_read_lane',file:'212_local_woo_read_lane.sql'}]);const index=plan.findIndex((r:any)=>r.name==='212_local_woo_read_lane');assert.deepEqual(plan[index-1],{name:'211_return_credit148_acceptance',file:'211_return_credit148_acceptance_install.sql'});assert.equal(plan.some((r:any)=>/^210_/.test(r.name)||/^210_/.test(r.file)),false,'split210 remains unregistered');});

