 assert.equal(f.state.controls.length,1);assert.equal(f.state.controls[0].enabled,false);assert.equal(f.state.controls[0].next_at,null);assert.equal(f.state.commands.length,1);const saved=structuredClone(f.state),at=f.sql.length;
 assert.deepEqual(await f.create().configure(f.actor,id(3),b),ack);assert.deepEqual(await f.lane.cancelCommand(f.actor,id(3),b),ack);assert.deepEqual(f.state,saved);assert(!f.sql.slice(at).some(q=>/^(INSERT|UPDATE|DELETE)/.test(q.text)));
