test('first processor failure retains safe phase and exact held IDs without altering or retrying the lease',async()=>{
 const secret='ck_private cs_private password '+ 'x'.repeat(12000),cause=Object.assign(new Error(secret),{code:'57014'}),f=fixture({processorCause:cause});await f.configure();
 await f.lane.cycle();const o=f.state.occurrences[0],job=f.state.jobs[0],dispatch=f.state.dispatches[0],held=structuredClone({o,job,dispatch});
 const d=await f.lane.readDiagnostic(f.actor,id(3),o.id);assert.equal(d.status,'RETAINED_FAILURE');assert.equal(d.phase,'processor');assert.equal(d.error_category,'POSTGRES');assert.equal(d.sqlstate,'57014');assert.equal(d.http_status,null);assert.equal(d.source,'memory');assert.equal(d.occurrence_id,o.id);assert.equal(d.job_id,job.id);assert.equal(d.dispatch_id,dispatch.id);assert.equal(d.error_fingerprint,crypto.createHash('sha256').update(Buffer.from(secret).subarray(0,8192)).digest('hex'));
 assert.equal(job.state,'running');assert.equal(job.attempts,1);assert(dispatch.lease_token);assert.equal(dispatch.state,'started');assert.equal(o.state,'running');
 const failures=f.state.audits.filter((x:any)=>x.action==='local_woo.read.failure');assert.equal(failures.length,1);assert(JSON.stringify(failures).length<2048);assert(!JSON.stringify([d,failures]).includes('private'));assert(!Object.hasOwn(d,'message'));assert(!Object.hasOwn(d,'stack'));assert(!Object.hasOwn(d,'lease_token'));
 const restarted=await f.create().readDiagnostic(f.actor,id(3),o.id);assert.deepEqual(restarted,{...d,source:'audit'});await f.lane.cycle();assert.equal(f.processed.length,1);assert.equal(f.state.audits.filter((x:any)=>x.action==='local_woo.read.failure').length,1);assert.deepEqual({o,job,dispatch},held);
});
