test('durable failure audit refuses changed held dispatch token, occurrence or job while preserving the first cause',async()=>{
 for(const failureCorruption of ['token','occurrence','job'] as const){const cause=Object.assign(new Error('first retained failure'),{code:'57014'}),f=fixture({processorCause:cause,failureCorruption});await f.configure();await f.lane.cycle();const o=f.state.occurrences[0],d=f.state.dispatches[0];
  assert.equal(f.state.audits.filter((x:any)=>x.action==='local_woo.read.failure').length,0);await assert.rejects(f.lane.readDiagnostic(f.actor,id(3),o.id));assert.equal(f.state.jobs[0].attempts,1);assert.equal(f.state.jobs[0].state,'running');
  if(failureCorruption==='token')f.state.dispatches[0].lease_token=f.state.jobs[0].lease_token;if(failureCorruption==='occurrence')f.state.dispatches[0].occurrence_id=o.id;if(failureCorruption==='job')f.state.occurrences[0].job_id=f.state.jobs[0].id;
  const retained=await f.lane.readDiagnostic(f.actor,id(3),o.id);assert.equal(retained.source,'memory');assert.equal(retained.sqlstate,'57014');assert.equal(retained.error_fingerprint,crypto.createHash('sha256').update(cause.message).digest('hex'));await f.lane.cycle();assert.equal(f.processed.length,1);
 }
});
test('durable audit cannot be attached to a different or missing dispatch on readback',async()=>{
 const f=fixture({processorCause:new Error('first')});await f.configure();await f.lane.cycle();const o=f.state.occurrences[0],reader=f.create(),d=f.state.dispatches[0];d.occurrence_id=id(999);await assert.rejects(reader.readDiagnostic(f.actor,id(3),o.id));d.occurrence_id=o.id;d.tenant_id=id(999);await assert.rejects(reader.readDiagnostic(f.actor,id(3),o.id));d.tenant_id=id(1);f.state.dispatches=[];await assert.rejects(reader.readDiagnostic(f.actor,id(3),o.id));
});

test('Postgres errors with an HTTP wrapper normalize to one safe category only',async()=>{
 const f=fixture({processorCause:Object.assign(new Error('wrapped SQL failure secret'),{code:'57014',status:503})});await f.configure();await f.lane.cycle();const d=await f.lane.readDiagnostic(f.actor,id(3),f.state.occurrences[0].id);assert.equal(d.error_category,'POSTGRES');assert.equal(d.sqlstate,'57014');assert.equal(d.http_status,null);assert.equal((await f.create().readDiagnostic(f.actor,id(3),d.occurrence_id)).http_status,null);const entry=f.state.audits.find((x:any)=>x.action==='local_woo.read.failure');entry.detail.evidence.http_status=503;await assert.rejects(f.create().readDiagnostic(f.actor,id(3),d.occurrence_id));
});

async function failedPaused(options:any={}){const f=fixture({processorCause:new Error('unconfirmed read'),...options});await f.configure();await f.lane.cycle();await f.configure('orders.sync',false,'1');const oid=f.state.occurrences[0].id,preview=await f.lane.previewAbort(f.actor,id(3),oid),body={client_key:id(901),expected_snapshot_sha256:preview.expected_snapshot_sha256,confirmed:true};return{f,oid,preview,body};}
test('server abort preview is fresh read-only and a full snapshot, then exact abort preserves original evidence and paused agreement',async()=>{
 const{f,oid,preview,body}=await failedPaused();const before=structuredClone(f.state),start=f.sql.length,p=await f.lane.previewAbort(f.actor,id(3),oid);assert.deepEqual(p,preview);assert.deepEqual(f.state,before);assert(f.sql.slice(start).every(q=>q.text.startsWith('SELECT')&&!q.text.includes('FOR UPDATE')));
 const ack=await f.lane.abortAttempt(f.actor,id(3),oid,body);assert.equal(ack.status,'LOCAL_WOO_READ_ATTEMPT_ABORTED');assert.equal(ack.original_outcome,'UNCONFIRMED');assert.equal(ack.control_version,'2');assert.equal(ack.enabled,false);assert.equal(f.state.occurrences[0].state,'aborted');assert.equal(f.state.occurrences[0].checkpoint_hash,before.occurrences[0].checkpoint_hash);assert(f.state.occurrences[0].finished_at);assert.equal(f.state.jobs[0].state,'failed');for(const k of ['attempts','max_attempts','payload','dedup_key'])assert.deepEqual(f.state.jobs[0][k],before.jobs[0][k]);assert.equal(f.state.jobs[0].lease_token,null);assert.equal(f.state.jobs[0].locked_at,null);assert.deepEqual(f.state.dispatches,before.dispatches);assert.deepEqual(f.state.controls,before.controls);assert.equal(f.state.reconciliations.length,1);assert.deepEqual(f.lane.inspect().stopped,[]);assert.equal((await f.lane.readOccurrence(f.actor,id(3),oid)).reconciliation_required,false);await f.lane.cycle();assert.equal(f.processed.length,1);
 const frozen=structuredClone(f.state);assert.deepEqual(await f.lane.abortAttempt(f.actor,id(3),oid,body),ack);assert.deepEqual(f.state,frozen);assert.deepEqual((await f.create().observeAbort(f.actor,id(3),oid,body)).ack,ack);assert.deepEqual(f.state,frozen);
});
test('preview hash detects exact checkpoint, lease, source, control and PG microsecond snapshot changes without mutation',async()=>{
 for(const mutate of [(f:any)=>f.state.occurrences[0].checkpoint_hash='f'.repeat(64),(f:any)=>{f.state.jobs[0].lease_token=id(991);f.state.dispatches[0].lease_token=id(991);},(f:any)=>f.state.jobs[0].locked_at='2026-10-19 12:02:00.123457+00',(f:any)=>f.state.controls[0].version='3',(f:any)=>f.state.ch.credentials='rotated',(f:any)=>f.state.jobs[0].payload.page=2]){const{f,oid,body}=await failedPaused();mutate(f);const before=structuredClone(f.state);await assert.rejects(f.lane.abortAttempt(f.actor,id(3),oid,body));assert.deepEqual(f.state,before);assert.equal(f.state.reconciliations.length,0);}
});
test('abort refuses enabled, foreign, revoked, catalog, acknowledged, multiple-dispatch and already-completed attempts',async()=>{
 for(const mutate of [(f:any)=>{f.state.controls[0].enabled=true;f.state.controls[0].next_at='2026-10-19T12:10:00Z';},(f:any)=>f.state.role='viewer',(f:any)=>f.state.occurrences[0].kind='catalog.fetch',(f:any)=>f.state.dispatches[0].state='acknowledged',(f:any)=>f.state.dispatches.push({...f.state.dispatches[0],id:id(992)}),(f:any)=>{f.state.jobs[0].state='done';f.state.jobs[0].attempts=0;f.state.jobs[0].lease_token=null;},(f:any)=>f.state.occurrences[0].owner_id=id(999)]){const{f,oid,body}=await failedPaused();mutate(f);const before=structuredClone(f.state);await assert.rejects(f.lane.abortAttempt(f.actor,id(3),oid,body));assert.deepEqual(f.state,before);}
 const{f,oid,body}=await failedPaused();for(const actor of [{...f.actor,tenantId:id(999)},{...f.actor,userId:id(999)},{...f.actor,role:'viewer'},{...f.actor,apiKeyId:id(999)}])for(const method of ['abortAttempt','observeAbort'])await assert.rejects(f.lane[method](actor,id(3),oid,body));
});
test('lost abort COMMIT ACK retains UNKNOWN and resolves from durable exact receipt without replay or implicit resume',async()=>{
 const{f,oid,body}=await failedPaused({unknownAbort:true});await assert.rejects(f.lane.abortAttempt(f.actor,id(3),oid,body),/abort COMMIT ACK unknown/);assert.equal(f.state.occurrences[0].state,'aborted');assert.equal(f.state.reconciliations.length,1);assert.equal(f.lane.inspect().stopped.length,1);const saved=structuredClone(f.state);
 const result=await f.lane.observeAbort(f.actor,id(3),oid,body);assert.equal(result.status,'ABORT_RESULT_ACKNOWLEDGED');assert.equal(result.ack.original_outcome,'UNCONFIRMED');assert.deepEqual(f.lane.inspect().stopped,[]);assert.deepEqual(f.state,saved);assert.deepEqual((await f.create().observeAbort(f.actor,id(3),oid,body)).ack,result.ack);await f.lane.cycle();assert.equal(f.processed.length,1);assert.equal(f.state.controls[0].enabled,false);
 for(const patch of [{expected_snapshot_sha256:'f'.repeat(64)},{confirmed:false},{extra:true}])await assert.rejects(f.lane.observeAbort(f.actor,id(3),oid,{...body,...patch}));
 assert.equal((await f.lane.observeAbort(f.actor,id(3),oid,{...body,client_key:id(999)})).status,'ABORT_RESULT_UNKNOWN');
});
test('two administrators serialize aborts to one receipt; stale second key cannot rewrite the terminal attempt',async()=>{
 const{f,oid,body}=await failedPaused(),other=f.create();const [a,b]=await Promise.all([f.lane.abortAttempt(f.actor,id(3),oid,body),other.abortAttempt(f.actor,id(3),oid,body)]);assert.deepEqual(a,b);assert.equal(f.state.reconciliations.length,1);const before=structuredClone(f.state);await assert.rejects(other.abortAttempt(f.actor,id(3),oid,{...body,client_key:id(999)}));assert.deepEqual(f.state,before);
});
test('abort before delayed staging fences late processor and clears only the exact aborted lane, then new work requires explicit fresh enable',async()=>{
 const f=fixture({hold:true});await f.configure();const work=f.lane.cycle();while(!f.release.fn)await new Promise(r=>setImmediate(r));await f.configure('orders.sync',false,'1');const oid=f.state.occurrences[0].id,p=await f.lane.previewAbort(f.actor,id(3),oid);await f.lane.abortAttempt(f.actor,id(3),oid,{client_key:id(902),expected_snapshot_sha256:p.expected_snapshot_sha256,confirmed:true});const before=structuredClone(f.state);f.release.fn();const result=await work;assert.equal(result[0].state,'ADMINISTRATIVELY_ABORTED');assert.deepEqual(f.state,before);assert.deepEqual(f.lane.inspect().stopped,[]);assert.equal(f.processed.length,1);assert.equal(f.state.jobs[0].state,'failed');assert.equal(f.state.dispatches[0].state,'started');await f.lane.cycle();assert.equal(f.processed.length,1);
 await f.configure('orders.sync',true,'2');const next=f.lane.cycle();while(f.processed.length<2)await new Promise(r=>setImmediate(r));f.release.fn();await next;assert.equal(f.state.occurrences.length,2);assert.notEqual(f.state.occurrences[1].id,oid);assert.notEqual(f.state.jobs[0].id,f.state.jobs[1].id);assert.equal(f.state.occurrences[0].state,'aborted');assert.equal(f.state.occurrences[1].state,'done');
});

test('processor staging and completion winning before abort makes the stale preview refuse without inventing rollback',async()=>{
 const f=fixture({hold:true});await f.configure();const work=f.lane.cycle();while(!f.release.fn)await new Promise(r=>setImmediate(r));await f.configure('orders.sync',false,'1');const oid=f.state.occurrences[0].id,p=await f.lane.previewAbort(f.actor,id(3),oid);f.release.fn();await work;const before=structuredClone(f.state);assert.equal(f.state.jobs[0].state,'done');await assert.rejects(f.lane.abortAttempt(f.actor,id(3),oid,{client_key:id(903),expected_snapshot_sha256:p.expected_snapshot_sha256,confirmed:true}));assert.deepEqual(f.state,before);assert.equal(f.state.reconciliations.length,0);
});
test('late finish after known abort cannot turn the administratively terminal occurrence into success',async()=>{
 const f=fixture({hold:true,processorReturnsWithoutAck:true});await f.configure();const work=f.lane.cycle();while(!f.release.fn)await new Promise(r=>setImmediate(r));await f.configure('orders.sync',false,'1');const oid=f.state.occurrences[0].id,p=await f.lane.previewAbort(f.actor,id(3),oid);await f.lane.abortAttempt(f.actor,id(3),oid,{client_key:id(904),expected_snapshot_sha256:p.expected_snapshot_sha256,confirmed:true});const before=structuredClone(f.state);f.release.fn();await work;assert.deepEqual(f.state,before);assert.equal(f.state.occurrences[0].state,'aborted');assert.equal(f.state.dispatches[0].state,'started');assert.deepEqual(f.lane.inspect().stopped,[]);
});
test('authoritative abort clears only the exact stopped scope and cannot clear a later or catalogue failure',async()=>{
 const{f,oid,body}=await failedPaused();await f.configure('catalog.fetch');await f.lane.cycle();assert.equal(f.lane.inspect().stopped.length,2);await f.lane.abortAttempt(f.actor,id(3),oid,body);assert.deepEqual(f.lane.inspect().stopped,[id(3)+':catalog.fetch']);await f.configure('orders.sync',true,'2');await f.lane.cycle();const later=f.state.occurrences.find((o:any)=>o.kind==='orders.sync'&&o.id!==oid);assert(later);assert(f.lane.inspect().stopped.includes(id(3)+':orders.sync'));const saved=structuredClone(f.state);await f.lane.observeAbort(f.actor,id(3),oid,body);assert.deepEqual(f.state,saved);assert(f.lane.inspect().stopped.includes(id(3)+':orders.sync'));assert(f.lane.inspect().stopped.includes(id(3)+':catalog.fetch'));
});

test('reading an older abort receipt cannot remove the fence for a newer administratively aborted in-flight read',async()=>{
 const f=fixture({hold:true});let old:any;
 for(let i=0;i<2;i++){await f.configure('orders.sync',true,String(i*2));const running=f.lane.cycle();while(f.processed.length<i+1||!f.release.fn)await new Promise(r=>setImmediate(r));await f.configure('orders.sync',false,String(i*2+1));const oid=f.state.occurrences.at(-1).id,p=await f.lane.previewAbort(f.actor,id(3),oid),body={client_key:id(910+i),expected_snapshot_sha256:p.expected_snapshot_sha256,confirmed:true};await f.lane.abortAttempt(f.actor,id(3),oid,body);
  if(i===0)old={oid,body};else await f.lane.observeAbort(f.actor,id(3),old.oid,old.body);
  f.release.fn();const outcome=await running;assert.equal(outcome[0].state,'ADMINISTRATIVELY_ABORTED');assert.deepEqual(f.lane.inspect().stopped,[]);
 }assert.equal(f.state.reconciliations.length,2);assert(f.state.jobs.every((j:any)=>j.state==='failed'&&j.attempts===1));assert(f.state.dispatches.every((d:any)=>d.state==='started'));
});


test('selected natural reader passes its exact held read to import staging and drains imports only after read ACK',async()=>{
 const events:string[]=[],ticket=Object.freeze({});let f:ReturnType<typeof fixture>;
 const orderImport={capture:async(s:any,occurrenceId:string)=>{events.push('capture');assert.deepEqual(s,f.scope);assert.equal(occurrenceId,f.state.occurrences[0].id);assert.equal(f.state.occurrences[0].state,'running');assert.equal(f.state.dispatches[0].state,'started');return ticket;},
 stage:async(c:any,t:object,anchor:any,created:any[])=>{events.push('stage');assert.equal(t,ticket);const o=f.state.occurrences[0],d=f.state.dispatches[0],j=f.state.jobs[0];assert.deepEqual(anchor,{occurrence_id:o.id,dispatch_id:d.id,read_job_id:j.id,lease_token:j.lease_token});assert.equal(j.state,'running');assert.equal(d.state,'started');assert.equal(typeof c.query,'function');assert.deepEqual(created,[{id:id(901),state:'staged',source_hash:'a'.repeat(64)}]);},
 cycle:async()=>{events.push('import');assert.equal(f.state.occurrences[0].state,'done');assert.equal(f.state.dispatches[0].state,'acknowledged');assert.equal(f.state.jobs[0].state,'done');assert.equal(f.state.jobs[0].lease_token,null);}};
 f=fixture({orderImport});await f.configure();await f.lane.cycle();assert.deepEqual(events,['capture','stage','import']);await f.lane.cycle();assert.deepEqual(events,['capture','stage','import','import'],'idle reader still drains admitted imports without rereading or adopting old jobs');assert.equal(f.processed.length,1);
});

test('pure read failure (409 page drift) ends the exact attempt terminally without parking; next due read runs',async()=>{
 const cause=Object.assign(new Error('Paginacja WooCommerce zmieniła się; wynik niepełny'),{status:409}),f=fixture({providerRead:{cause,times:1}});await f.configure();
 const outcomes=await f.lane.cycle();const o=f.state.occurrences[0],job=f.state.jobs[0],dispatch=f.state.dispatches[0];
 assert.deepEqual(outcomes,[{channel_id:id(3),kind:'orders.sync',state:'READ_FAILED_NO_EFFECT'}]);
 assert.equal(job.state,'failed');assert.equal(job.lease_token,null);assert.equal(job.attempts,1);assert.match(job.error,/bez skutku/);
 assert.equal(o.state,'aborted');assert(o.finished_at);assert.equal(dispatch.state,'acknowledged');assert.match(dispatch.after_hash,/^[a-f0-9]{64}$/);
 assert.deepEqual(f.lane.inspect().stopped,[]);
 const d=await f.lane.readDiagnostic(f.actor,id(3),o.id);assert.equal(d.status,'RETAINED_FAILURE');assert.equal(d.phase,'provider_read');assert.equal(d.http_status,409);
 const closed=f.state.audits.filter((x:any)=>x.action==='local_woo.read.no_effect');assert.equal(closed.length,1);assert.deepEqual(closed[0].detail,{job_id:job.id,dispatch_id:dispatch.id,phase:'provider_read',outcome:'NO_EFFECT_READ_FAILED',automatic_retry:false});
 const detail=await f.lane.readOccurrence(f.actor,id(3),o.id);assert.equal(detail.reconciliation_required,false);
 f.state.controls[0].due=true;await f.lane.cycle();
 assert.equal(f.state.occurrences.length,2);assert.equal(f.state.occurrences[1].state,'done');assert.equal(f.state.jobs[1].state,'done');assert.equal(f.processed.length,2);
 // A later failure is retained again; the first closure does not hide it.
 f.options.providerRead={cause,times:1};f.state.controls[0].due=true;await f.lane.cycle();assert.equal(f.state.occurrences[2].state,'aborted');assert.equal((await f.lane.readDiagnostic(f.actor,id(3),f.state.occurrences[2].id)).occurrence_id,f.state.occurrences[2].id);assert.deepEqual(f.lane.inspect().stopped,[]);
});
test('read failure whose lease is no longer exactly held is NOT closed: channel parks for reconciliation',async()=>{
 const f=fixture({providerRead:{cause:Object.assign(new Error('drift'),{status:409}),times:1,stealLease:true}});await f.configure();
 const outcomes=await f.lane.cycle();assert.deepEqual(outcomes,[{channel_id:id(3),kind:'orders.sync',state:'RECONCILIATION_REQUIRED'}]);
 assert.equal(f.state.jobs[0].state,'running');assert.equal(f.state.dispatches[0].state,'started');assert.equal(f.state.occurrences[0].state,'running');
 assert.deepEqual(f.lane.inspect().stopped,[id(3)+':orders.sync']);assert.equal(f.state.audits.filter((x:any)=>x.action==='local_woo.read.no_effect').length,0);
});

test('pause between the eligibility read and the claim is inert (no stop, no held attempt); resume runs the next due read',async()=>{
 // Stock-lane dry run -70 parked channels on a schedule pause; the read lane's claim treats a paused control as idle.
 let once=true;const f=fixture({afterEligible:st=>{if(once){once=false;const c=st.controls[0];Object.assign(c,{enabled:false,version:String(Number(c.version)+1),next_at:null,due:false});}}});
 await f.configure();const r=await f.lane.cycle();assert.deepEqual(r,[]);assert.deepEqual(f.lane.inspect().stopped,[]);assert.equal(f.processed.length,0);assert.equal(f.state.jobs.length,0);
 const resumed=await f.configure('orders.sync',true,'2');assert.equal(resumed.version,'3');f.state.controls[0].due=true;
 const next=await f.lane.cycle();assert.equal(next[0].state,'done');assert.deepEqual(f.lane.inspect().stopped,[]);assert.equal(f.processed.length,1);
});
